from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """ Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    """
    if not isinstance(numbers, list) or not all(isinstance(n, (int, float)) for n in numbers):
        raise TypeError("numbers must be a list of integers or floats")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")

    if threshold < 0:
        return False

    sorted_numbers = sorted(numbers)
    for first, second in zip(sorted_numbers, sorted_numbers[1:]):
        if second - first < threshold:
            return True
    return False
```

